static class comparador implements Comparator<String> {

    public int compare(String cadena1, String cadena2) {

        int resultado = cadena1.compareTo(cadena2);

        // Cambiamos a orden descendente
        if(resultado < 0)
            resultado = 1;
        else
            resultado = -1;

        return resultado;
    }

}
